Input: {"question": "When was General Ritchie born?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 0, "end": 195, "text": "Andrew Ritchie (British Army officer) Major-General Andrew Stephenson Ritchie, CBE (born 30 July 1953) is a retired British officer and former Commandant of the Royal Military Academy, Sandhurst."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 196, "end": 245, "text": "He is now Director of Goodenough College, London."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 246, "end": 298, "text": "Ritchie was born on 30 July 1953 in London, England."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 299, "end": 372, "text": "He is the son of Dilys (née Stephenson) and Canon David Caldwell Ritchie."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 373, "end": 430, "text": "He was educated at Harrow County Boys' School until 1971."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 431, "end": 593, "text": "While serving in the British Army, he was able to attend the University of Durham between 1975 and 1978, where he gained a third-class degree in Law and Politics."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0345-9a2292cb5682:d00", "start": 594, "end": 605, "text": "Ritchie was"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0345-9a2292cb5682:d01", "start": 0, "end": 619, "text": "decorations 6 References Toggle the table of contents Andrew Ritchie ( British Army officer ) Add languages Add links Article Talk English Read Edit View history Tools Tools move to sidebar hide Actions Read Edit View history General What links here Related changes Upload file Permanent link Page information Cite this page Get shortened URL Download QR code Print/export Download as PDF Printable version In other projects Wikidata item Appearance move to sidebar hide From Wikipedia , the free encyclopedia British Army general ( born 1953 ) Andrew Stephenson Ritchie Ritchie in 2005 Born ( 1953-07-30 ) 30 July 1953"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0345-9a2292cb5682:d02", "start": 0, "end": 478, "text": "( age 71 ) Allegiance United Kingdom Service / branch British Army Years of service 1973–2006 Rank Major-General Service number 495574 Commands Royal Military Academy Sandhurst 4th Division 1st Royal Horse Artillery Awards Commander of the Order of the British Empire Queen 's Commendation for Valuable Service Major General Andrew Stephenson Ritchie , CBE ( born 30 July 1953 ) is a retired British Army officer and former Commandant of the Royal Military Academy , Sandhurst ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0345-9a2292cb5682:d02", "start": 479, "end": 527, "text": "He was Director of Goodenough College , London ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0345-9a2292cb5682:d02", "start": 528, "end": 590, "text": "Early life [ edit ] Ritchie was born on 30 July 1953 in London"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0345-9a2292cb5682:d03", "start": 0, "end": 615, "text": "decorations 6 References Toggle the table of contents Andrew Ritchie (British Army officer) Add languages Add links Article Talk English Read Edit View history Tools Tools move to sidebar hide Actions Read Edit View history General What links here Related changes Upload file Permanent link Page information Cite this page Get shortened URL Download QR code Print/export Download as PDF Printable version In other projects Wikidata item Appearance move to sidebar hide From Wikipedia, the free encyclopedia British Army general (born 1960) Andrew Stephenson Ritchie Ritchie in 2005 Born (1960-01-15) 15 January 1960"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0345-9a2292cb5682:d04", "start": 0, "end": 473, "text": "(age 71) Allegiance United Kingdom Service / branch British Army Years of service 1973–2006 Rank Major-General Service number 495574 Commands Royal Military Academy Sandhurst 4th Division 1st Royal Horse Artillery Awards Commander of the Order of the British Empire Queen's Commendation for Valuable Service Major General Andrew Stephenson Ritchie, CBE (born 15 January 1955) is a retired British Army officer and former Commandant of the Royal Military Academy, Sandhurst."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0345-9a2292cb5682:d04", "start": 474, "end": 520, "text": "He was Director of Goodenough College, London."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0345-9a2292cb5682:d04", "start": 521, "end": 585, "text": "Early life [edit] Ritchie was born on 15 January 1955 in London."}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0345-9a2292cb5682:d05", "start": 0, "end": 250, "text": "Archibald Ritchie (British Army officer) Major-General Sir Archibald Buchanan Ritchie, KBE CB CMG (14 May 1869 - 9 July 1955) was a British Army officer, who commanded the 11th (Northern) Division and 16th (Irish) Division during the First World War."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0345-9a2292cb5682:d05", "start": 251, "end": 373, "text": "Ritchie was born in 1869, the son of John Ritchie, an artillery officer who would later rise to the rank of Major-General."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0345-9a2292cb5682:d05", "start": 374, "end": 512, "text": "He was educated at the United Services College and the Royal Military College, Sandhurst, before joining the Seaforth Highlanders on 1889."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0345-9a2292cb5682:d05", "start": 513, "end": 594, "text": "He saw service in the Nile Campaign of 1898, and was promoted to captain on 2 May"}, "D7S1": {"document_number": 7, "doc_id": "ramdocs-0345-9a2292cb5682:d06", "start": 0, "end": 31, "text": "United States military history."}, "D7S2": {"document_number": 7, "doc_id": "ramdocs-0345-9a2292cb5682:d06", "start": 32, "end": 144, "text": "Ritchie was born June 25, 1942, in Reidsville, North Carolina, the son of an American Tobacco Company executive."}, "D7S3": {"document_number": 7, "doc_id": "ramdocs-0345-9a2292cb5682:d06", "start": 145, "end": 250, "text": "He was a star quarterback for Reidsville High School, despite breaking his leg twice, graduating in 1960."}, "D7S4": {"document_number": 7, "doc_id": "ramdocs-0345-9a2292cb5682:d06", "start": 251, "end": 529, "text": "In 1964, he graduated with a Bachelor of Science degree in Engineering Science from the United States Air Force Academy, where, as a \"walk-on\", he became the starting halfback for the Falcons varsity football team in 1962 and 1963, playing his final game in the 1963 Gator Bowl."}, "D7S5": {"document_number": 7, "doc_id": "ramdocs-0345-9a2292cb5682:d06", "start": 530, "end": 596, "text": "Ritchie was described by his peers as being a jock, and by General"}, "D8S1": {"document_number": 8, "doc_id": "ramdocs-0345-9a2292cb5682:d07", "start": 0, "end": 271, "text": "Ritchie received the 1972 Mackay Trophy for the most significant Air Force mission of the year and the Colonel James Jabara Award from the Air Force Academy and in 1973 he was presented the VFW Armed Forces Award for outstanding Air Force professionalism and leadership ."}, "D8S2": {"document_number": 8, "doc_id": "ramdocs-0345-9a2292cb5682:d07", "start": 272, "end": 487, "text": "Leaving active duty in April 1974 , Ritchie remained in the Air Force Reserves and became active in his own business as a speaker and consultant , advocating the free-market economy in all spheres of American life ."}, "D8S3": {"document_number": 8, "doc_id": "ramdocs-0345-9a2292cb5682:d07", "start": 488, "end": 556, "text": "He was promoted to brigadier general in the Reserves in April 1994 ."}, "D8S4": {"document_number": 8, "doc_id": "ramdocs-0345-9a2292cb5682:d07", "start": 557, "end": 572, "text": "Share this post"}, "D9S1": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 0, "end": 41, "text": "the land forces in the Far East in 1947 ."}, "D9S2": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 42, "end": 156, "text": "After retiring from the British Army he was chairman of the Mercantile and General Reinsurance Company in Canada ."}, "D9S3": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 157, "end": 184, "text": "Neil Ritchie died in 1983 ."}, "D9S4": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 185, "end": 280, "text": "By John Simkin ( john @ spartacus-educational.com ) © September 1997 ( updated January 2020 ) ."}, "D9S5": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 281, "end": 435, "text": "▲ Main Article ▲ Primary Sources ( 1 ) ( 1 ) Bernard Montgomery , The Memoirs of Field Marshal Montgomery ( 1958 ) Auchinleck was a poor picker of men , ."}, "D9S6": {"document_number": 9, "doc_id": "ramdocs-0345-9a2292cb5682:d08", "start": 436, "end": 513, "text": "A good judge of men would never have selected General Corbett to be his Chief"}}, "original_cards": [{"doc_id": "ramdocs-0345-9a2292cb5682:d00", "card_id": "ramdocs-0345-9a2292cb5682:d00:c0", "entity": "General Ritchie", "scope": "Birth date", "claim": "General Ritchie was born on 30 July 1953.", "answer": "30 July 1953", "quote": "Andrew Ritchie (British Army officer) Major-General Andrew Stephenson Ritchie, CBE (born 30 July 1953) is a retired British officer and former Commandant of the Royal Military Academy, Sandhurst. He is now Director of Goodenough College, London. Ritchie was born on 30 July 1953 in London, England.", "original_document_number": 1}, {"doc_id": "ramdocs-0345-9a2292cb5682:d01", "card_id": "ramdocs-0345-9a2292cb5682:d01:c0", "entity": "Andrew Stephenson Ritchie", "scope": "British Army general", "claim": "Andrew Stephenson Ritchie was born on 30 July 1953.", "answer": "30 July